export function useGetPayments<TData = Awaited<ReturnType<typeof getPayments>>, TError = ErrorType<unknown>>(
  options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getPayments>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetPaymentsQueryOptions(options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







export const getInitiatePaymentUrl = () => {




  return `/api/payments/initiate`
}

/**
 * @summary Initiate a payment (MoMo simulation for MVP)
 */
export const initiatePayment = async (initiatePaymentRequest: InitiatePaymentRequest, options?: RequestInit): Promise<Payment> => {

  return customFetch<Payment>(getInitiatePaymentUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(initiatePaymentRequest)
  }
);}





export const getInitiatePaymentMutationOptions = <TError = ErrorType<ErrorResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof initiatePayment>>, TError,{data: BodyType<InitiatePaymentRequest>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof initiatePayment>>, TError,{data: BodyType<InitiatePaymentRequest>}, TContext> => {

const mutationKey = ['initiatePayment'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof initiatePayment>>, {data: BodyType<InitiatePaymentRequest>}> = (props) => {
          const {data} = props ?? {};

          return  initiatePayment(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type InitiatePaymentMutationResult = NonNullable<Awaited<ReturnType<typeof initiatePayment>>>
    export type InitiatePaymentMutationBody = BodyType<InitiatePaymentRequest>
    export type InitiatePaymentMutationError = ErrorType<ErrorResponse>

    /**
 * @summary Initiate a payment (MoMo simulation for MVP)
 */
export const useInitiatePayment = <TError = ErrorType<ErrorResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof initiatePayment>>, TError,{data: BodyType<InitiatePaymentRequest>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof initiatePayment>>,
        TError,
        {data: BodyType<InitiatePaymentRequest>},
        TContext
      > => {
      return useMutation(getInitiatePaymentMutationOptions(options));
    }

